solution.exercise.c:
#include "exercise.h"
#include <ctype.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static int inverse(int a) {
    a = (a % 26 + 26) % 26;
    for (int i = 1; i < 26; i++)
        if (a * i % 26 == 1)
            return i;
    return -1;
}
static bool cipher(const char *t, int a, int b, char *out, bool enc) {
    int inv = inverse(a);
    if (inv < 0)
        return false;
    size_t n = 0;
    for (; *t; t++) {
        unsigned char c = (unsigned char)tolower((unsigned char)*t);
        if (!isalnum(c))
            continue;
        if (enc && n && n % 5 == 0)
            *out++ = ' ';
        if (isalpha(c)) {
            int x = enc ? a * (c - 'a') + b : inv * ((c - 'a') - b);
            c = (unsigned char)('a' + (x % 26 + 26) % 26);
        }
        *out++ = (char)c;
        n++;
    }
    *out = 0;
    return true;
}
bool encode(const char *t, int a, int b, char *out) {
    return cipher(t, a, b, out, true);
}
bool decode(const char *t, int a, int b, char *out) {
    return cipher(t, a, b, out, false);
}

