#include "exercise.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static bool positive(int x) { return x > 0; }
static bool bstring(const void *p) { return (*(const char *const *)p)[0] == 98; }
static void string_length(const void *p, void *out) {
    *(size_t *)out = strlen(*(const char *const *)p);
}
int main(void) {
    char o[200];
    assert(encode("yes", 5, 7, o) && !strcmp(o, "xbt"));
    assert(encode("Testing,1 2 3, testing.", 3, 4, o) &&
           !strcmp(o, "jqgjc rw123 jqgjc rw"));
    assert(decode("xbt", 5, 7, o) && !strcmp(o, "yes"));
    assert(!encode("test", 6, 17, o));
    {
        char actual[1000];
        assert(encode("yes", 5, 7, actual));
        assert(!strcmp(actual, "xbt"));
    }
    {
        char actual[1000];
        assert(encode("no", 15, 18, actual));
        assert(!strcmp(actual, "fu"));
    }
    {
        char actual[1000];
        assert(encode("OMG", 21, 3, actual));
        assert(!strcmp(actual, "lvz"));
    }
    {
        char actual[1000];
        assert(encode("O M G", 25, 47, actual));
        assert(!strcmp(actual, "hjp"));
    }
    {
        char actual[1000];
        assert(encode("mindblowingly", 11, 15, actual));
        assert(!strcmp(actual, "rzcwa gnxzc dgt"));
    }
    {
        char actual[1000];
        assert(encode("Testing,1 2 3, testing.", 3, 4, actual));
        assert(!strcmp(actual, "jqgjc rw123 jqgjc rw"));
    }
    {
        char actual[1000];
        assert(encode("Truth is fiction.", 5, 17, actual));
        assert(!strcmp(actual, "iynia fdqfb ifje"));
    }
    {
        char actual[1000];
        assert(encode("The quick brown fox jumps over the lazy dog.", 17, 33, actual));
        assert(!strcmp(actual, "swxtj npvyk lruol iejdc blaxk swxmh qzglf"));
    }
    {
        char actual[1000];
        assert(decode("tytgn fjr", 3, 7, actual));
        assert(!strcmp(actual, "exercism"));
    }
    {
        char actual[1000];
        assert(decode("qdwju nqcro muwhn odqun oppmd aunwd o", 19, 16, actual));
        assert(!strcmp(actual, "anobstacleisoftenasteppingstone"));
    }
    {
        char actual[1000];
        assert(decode("odpoz ub123 odpoz ub", 25, 7, actual));
        assert(!strcmp(actual, "testing123testing"));
    }
    {
        char actual[1000];
        assert(decode("swxtj npvyk lruol iejdc blaxk swxmh qzglf", 17, 33, actual));
        assert(!strcmp(actual, "thequickbrownfoxjumpsoverthelazydog"));
    }
    {
        char actual[1000];
        assert(decode("swxtjnpvyklruoliejdcblaxkswxmhqzglf", 17, 33, actual));
        assert(!strcmp(actual, "thequickbrownfoxjumpsoverthelazydog"));
    }
    {
        char actual[1000];
        assert(decode("vszzm    cly   yd cg    qdp", 15, 16, actual));
        assert(!strcmp(actual, "jollygreengiant"));
    }
    return 0;
}
